using System;
using System.IO;
using System.Threading;
namespace JonsboStudio {
 static class ConnectionTests {
  sealed class Fake:IDisplayTransport {public bool fail;public volatile bool disposed;public ManualResetEvent entered,release;public string serial="TEST";public string SerialNumber{get{return serial;}}public int NativeWidth{get{return 320;}}public int NativeHeight{get{return 100;}}public void Connect(string port){}public void Send(byte[] jpeg){if(entered!=null){entered.Set();release.WaitOne();}if(fail)throw new IOException("USB removed");}public void Dispose(){disposed=true;}}
  static void Assert(bool value,string message){if(!value)throw new Exception("Connection test: "+message);}
  public static void Run(){using(var stop=new ManualResetEvent(false)){
   int created=0,logs=0;Fake first=null;using(var a=new DeviceConnection("old-port",()=>{var fake=new Fake();if(created++==0)first=fake;return fake;},port=>created>1?"new-port":port,error=>logs++))using(var b=new DeviceConnection("other",()=>new Fake(),port=>port,error=>{})){
    a.Connect();b.Connect();first.fail=true;Assert(!a.Send(t=>t.Send(new byte[0]))&&!a.Connected&&a.State=="reconnecting"&&first.disposed&&logs==1,"USB failure should release only its transport and queue recovery");Assert(b.Connected&&b.Send(t=>t.Send(new byte[0])),"other display must continue sending");
    a.RequestReconnect();Assert(a.EnsureConnected(stop)&&a.Connected&&a.Port=="new-port","manual reconnect should skip backoff and adopt the recovered port");Assert(a.Send(t=>t.Send(new byte[0])),"sending should resume after reconnect");
    a.RequestReconnect();Assert(a.EnsureConnected(stop)&&created==3,"manual reconnect while healthy must create a new transport");stop.Set();Assert(!a.EnsureConnected(stop),"stop must interrupt recovery");
   }
   stop.Reset();int attempts=0;using(var a=new DeviceConnection("missing",()=>{attempts++;throw new IOException("Unplugged");},port=>port,error=>{})){Assert(!a.EnsureConnected(stop)&&attempts==1,"initial retry failure must not escape");Assert(!a.EnsureConnected(stop)&&attempts==1,"backoff must avoid a busy retry loop");}
   var topology=new[]{new DeviceInfo{port="COM42",name="JONSBO DS916",hardwareId="original"}};Assert(DeviceConnection.ResolvePort("COM12","original",topology)=="COM42","DS916 COM renumbering must follow hardware identity");Assert(DeviceConnection.ResolvePort("COM12","changed-socket",topology)=="COM42","a unique DS916 may be probed after a socket change, then serial-validated");
   using(var entered=new ManualResetEvent(false))using(var release=new ManualResetEvent(false))using(var cleaned=new ManualResetEvent(false)){var guard=new DeviceStartup();bool cancelled=false;try{try{guard.Start("blocked",()=>{entered.Set();release.WaitOne();},()=>cancelled=true,()=>cleaned.Set(),30).GetAwaiter().GetResult();throw new Exception("No startup timeout");}catch(TimeoutException){}Assert(cancelled&&guard.IsPending("blocked"),"blocked startup must time out without freeing its in-flight operation");try{guard.Start("blocked",()=>{},()=>{},()=>{},30).GetAwaiter().GetResult();throw new Exception("Duplicate startup allowed");}catch(IOException){}guard.Start("other",()=>{},()=>{},()=>{},1000).GetAwaiter().GetResult();Assert(guard.IsPending("blocked"),"another device must start independently of a blocked driver");}finally{release.Set();Assert(cleaned.WaitOne(2000),"cleanup must run only after the blocked call returns");}}
   var doc=new ThemeDocument{Json=ThemeDocument.Blank("USB recovery test "+Guid.NewGuid().ToString("N"),320,100),Folder=AppPaths.Root,Background="",Video=false};var config=new StudioSettings{Port="TEST",Width=320,Height=100,Fps=60,Quality=75,CacheMB=32};int made=0;Fake failed=null;using(var engine=new PlaybackEngine(doc,config,true,()=>{var fake=new Fake{fail=made++==0};if(fake.fail)failed=fake;return fake;})){engine.Start();var deadline=System.Diagnostics.Stopwatch.StartNew();while(engine.Sent<20&&engine.Error.Length==0&&deadline.ElapsedMilliseconds<6000)Thread.Sleep(20);Assert(engine.ConnectionGeneration>=2&&engine.Sent>=20&&failed.disposed&&engine.Error.Length==0,"the actual playback sender must recover automatically after a transport failure");}
   using(var entered=new ManualResetEvent(false))using(var release=new ManualResetEvent(false)){var fake=new Fake{entered=entered,release=release};var blocked=new PlaybackEngine(doc,config,true,()=>fake);try{blocked.Start();Assert(entered.WaitOne(3000),"fake USB call did not start");blocked.Dispose();Assert(!fake.disposed,"an in-flight USB call must keep its transport and frame buffers alive");}finally{release.Set();var deadline=System.Diagnostics.Stopwatch.StartNew();while(!fake.disposed&&deadline.ElapsedMilliseconds<3000)Thread.Sleep(10);blocked.Dispose();}Assert(fake.disposed,"deferred USB resources must close after the driver call returns");}
   Assert(DeviceConnection.RetryDelay(1)==1000&&DeviceConnection.RetryDelay(2)==2000&&DeviceConnection.RetryDelay(20)==8000,"retry delay must be bounded");
   Assert(!DeviceConnection.Recoverable(new ArgumentException("bad frame")),"programming errors must not be retried as USB failures");
  }Console.WriteLine("PASS: unplug/send failure, independent devices, manual reconnect, port rebinding, stop cancellation and bounded automatic retry.");}
 }
}
